isVisible:
{{
  [
    Rating51Copy.value,
    Rating52Copy.value,
    Rating53Copy.value,
    Rating54Copy.value,
		Rating55Copy.value
  ].every(r => r >= 1)
}}

text:
{{
  (() => {
    const valori = [
      Rating51Copy.value,
      Rating52Copy.value,
      Rating53Copy.value,
      Rating54Copy.value,
      Rating55Copy.value
    ];

    const tuttiZero = valori.every(v => v === 0);
    const tuttiAlmenoTre = valori.every(v => v >= 3);

    return tuttiZero ? "" : (tuttiAlmenoTre ? "IDONEO" : "NON IDONEO");
  })()
}}

textColor:
{{
  (() => {
    const somma =
      Rating51Copy.value +
      Rating52Copy.value +
      Rating53Copy.value +
      Rating54Copy.value +
			Rating55Copy.value;

    return somma === 0 ? "" : (somma >= 15 ? "green" : "red");
  })()
}}
